      SUBROUTINE SECORNC---- NON-MIDPLANE-SYMMETRIC SECOND-ORDER INTEGRALS OF PRODUCTS OFC---- CHARACTERISTIC FUNCTIONS AND TRANSFER MATRIX ELEMENTS FOR AC---- COMBINED-FUNCTION BENDING MAGNETC----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM4D.CIN'      INCLUDE 'HSINT.CIN'      INCLUDE 'HSINTA.CIN'      INCLUDE 'HPINT.CIN'      INCLUDE 'HPINTA.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'      INCLUDE 'VSINT.CIN'      INCLUDE 'VSINTA.CIN'      INCLUDE 'VPINT.CIN'      INCLUDE 'VPINTA.CIN'      INCLUDE 'WMN.CIN'      INCLUDE 'WM5N.CIN'C ---------------------------------------------------------------------      REAL            BMTNP, DMSLV, FNM4      REAL            GLUG1, GLUG2, GLUG3, GLUG4, GLUG5, GLUG6, GLUG7,     1                GLUG8, GLUG9, GLUGA, GLUGB, GLUGC, GLUGD, GLUGE,     2                GLUGF, GLUGG, GLUGH, GLUGI, GLUGJ      REAL            NMB, NMTB, NPMV      REAL            SMLCV, SNARK, TBMNP, TBTNP, TMN, TNMB, TVMNP,      1                WM2N, WP2RC      WP2R = 1.0 + 2.0*RMPSC      NMB = NB - BEB      NMTB = NB - 2.0*BEB      TMN = 2.0 - NB      TNMB = 2.0*NB - BEB - 1.0      WM2N = 1.0 - 2.0*NB + 2.0*RMPS*(1.0 - NB)      FNM4 = 5.0*NB - 4.0 + RMPS*(5.0*NB - 8.0)C      NPMV = NPR - VR      TVMNP = 2.0*VR - NPR      TBMNP = 2.0*BEP - NPR - VR      TBTNP = 2.0*BEP - 3.0*NPR + VR      BMTNP = BEP - 2.0*NPRC      HSCY = (WMN*DISN - NBR*DSVN)/WM2N      HSSY = (SY - SX)/WM2N      HSLCY = ((2.0*NB*RH*SY - WP2R*SX)/WM2N + L*CY)/WM2N      HSLSY = (2.0*(NBR*DSVN - WMN*DISN)/WM2N     1 + L*SY)/WM2N      IF (NB .NE. 0.0) HSGLP = (HSSY - HSLCY)/NB      IF (NB .EQ. 0.0) HSGLP = (H*H0)**2*L**5/60.0      HSCCM = (NBR*CX*DSVN - 2.*WMN*SX*SY)/FNM4      HSCSM = - CX*SY/FNM4 + 0.5*H0**2*SX*DSVN     1 + 0.5*SX*(1.0 + CY)/FNM4      HSSCM = (2.0*CX*SY - SX*(1.0 + CY))/FNM4      HSSSM = 2.0*CX*DSVN/FNM4 - SX*SY/FNM4      HSDCM = RH*(- CX*(1.0 - CY)/(WMN*FNM4)     1 - (CX - CY)/(WMN*WM2N) + 2.0*H0**2*SX*SY/FNM4)      HSCDY = 0.5*RH*(1.0 - 3.0*WMN/WM5N)*DISN/WM2N     1 - RH*DSVN/WM2N + RH*SY**2/WM5N      HSDSM = RH*(CX*SY/(WMN*FNM4) - 0.5*SX*CY/(WMN*FNM4)     1 - (1.0/WM2N + 0.5/FNM4)*SX/WMN     2 + SY/(WMN*WM2N)) - 0.5*H*H0*SX*DSVN/WMN      HSSDY = 3.0*RH*(SX - SY)/(WM2N*WM5N)     1 + H*H0*SY*DSVN/WM5N      HPCY = (WMN*SX - NBR*SY)/WM2N      HPSY = (WMN*DISN - NBR*DSVN)/WM2N      HPLCY = (WP2R*(WMN*DISN - NBR*DSVN)/WM2N - NBR*L*SY)/WM2N      HPLSY = ((WP2R*SY - 2.0*WMN*SX)/WM2N + L*CY)/WM2N      IF (NB .NE. 0.0) HPGLP = (HPSY - HPLCY)/NB      IF (NB .EQ. 0.0)     1 HPGLP = ( - 2.0*DISN + L**2)/WMN      HPCCM = 0.5*CX*SY*(1.0 + RH*NB/FNM4)     1 - WMN*SX*(1.0 + CY)/FNM4      HPCSM = 0.5*CX*DSVN*(1.0 + NBR/FNM4) - WMN*SX*SY/FNM4      HPSCM = - NBR*CX*DSVN/FNM4 + 0.5*SX*SY*(1.0 + NBR/FNM4)      HPSSM = 0.5*H*H0*SX*DSVN/RH - 0.5*SX*(1.0 + CY)/FNM4     1 + CX*SY/FNM4      HPDCM = RH*(SX/WM2N + SX*(1.0 + CY)/FNM4     1 - RH*NB*SY/(WMN*WM2N)     2 - 0.5*(1.0 + RH*NB/FNM4)*CX*SY/WMN)      HPCDY = RH*(0.5*SX/WM2N - 1.5*WMN*SX/(WM2N*WM5N))     1 + 2.0*RH*CY*SY/WM5N - RH*SY/WM2N      HPDSM = - 0.5*RH*(1.0 + NBR/FNM4)*CX*DSVN/WMN     1 + RH*(WMN*DISN - NBR*DSVN)/(WMN*WM2N) + RH*SX*SY/FNM4      HPSDY = 3.0*RH*(CX - CY)/(WM5N*WM2N)     1 - H*H0*DSVN/WM5N + 2.0*H*H0*SY**2/WM5N      VSCX = (WMN*DISN - NBR*DSVN)/WM2N      VSSX = (SY - SX)/WM2N      VSDX = RH*((NBR*DSVN - WMN*DISN)/(WMN*WM2N) + DSVN/WMN)      IF (NB .EQ. 0.0) DMSLV = H0*H*L**4/24.0      IF (NB .NE. 0.0) DMSLV = (DSVN - 0.5*L*SY)/NB      VSDY = DMSLV      VSLCX = ((2.0*WMN*SX - WP2R*SY)/WM2N - L*CX)/WM2N      VSLSX = (2.0*(WMN*DISN - NBR*DSVN)/WM2N - L*SX)/WM2N      VSCX2 = 0.5*(1.0 + NBR/FNM4)*DSVN - WMN*SX**2/FNM4      VSCSX = (CX*SX - SY)/FNM4      VSSX2 = 0.5*(1.0 - NBR/FNM4)*DSVN/WMN + SX**2/FNM4      VSCY2 = (DSVN + SY**2)/3.0      VSCSY = SY*DSVN/3.0      IF (NB .EQ. 0.0) SNARK = 0.25*H0**2*L**4      IF (NB .NE. 0.0) SNARK = (2.0*DSVN - SY**2)/(NB*RH)      VSSY2 = SNARK/3.0      VSCDX = - 0.5*H*H0*(1.0 + NBR/FNM4)*DSVN/WMN     1 - RH*(CX - CY)/(WMN*WM2N) + H*H0*SX**2/FNM4      VSCDM = - H*H0*CX*DSVN/WM5N + 3.0*RH*(CX - CY)/(WM2N*WM5N)     1 + 2.0*H*H0*SX*SY/WM5N      VSSDX = RH*( - CX*SX/FNM4 - SX/WM2N     1 + SY*(1.0/WM2N + 1.0/FNM4))/WMN      VSSDM = - 2.0*RH*CX*SY/(WMN*WM5N)     1 + 0.5*RH*(1.0/WMN - 3.0/WM5N)*SY/WM2N     2 + 3.0*RH*SX/(WM2N*WM5N) - H*H0*SX*DSVN/WM5N      VSDX2 = RH*(2.0*RH*(NBR*DSVN - WMN*DISN)/(WMN**2*WM2N)     1 - RH*SX**2/(WMN*FNM4)     2 + 0.5*RH*(3.0 + NBR/FNM4)*DSVN/WMN**2)      VSDDM = RH*((RH*CX*DSVN/WM5N     1 + 3.0*RH*(WMN*DISN - NBR*DSVN)/(WM2N*WM5N)     2 - 2.0*RH*SX*SY/WM5N + DMSLV)/WMN)      VPCX = (WMN*SX - RH*NB*SY)/WM2N      VPSX = (WMN*DISN - NBR*DSVN)/WM2N      VPDX = RH*(SY - SX)/WM2N      IF (NB .EQ. 0.0) SMLCV = H0**2*L**3/3.0      IF (NB .NE. 0.0) SMLCV = (SY - L*CY)/NB      VPDY = 0.5*SMLCV      VPLCX = (WP2R*(CX - CY)/WM2N + H0**2*WMN*L*SX)/WM2N      VPLSX = ((WP2R*SX - 2.0*NB*RH*SY)/WM2N - L*CX)/WM2N      VPCX2 = 0.5*(1.0 + RH*NB/FNM4)*SY     1 - 2.0*WMN*CX*SX/FNM4      VPCSX = (NBR*DSVN - 2.0*WMN*SX**2)/FNM4      VPSX2 = 0.5*(1.0 - RH*NB/FNM4)*SY/WMN + 2.0*CX*SX/FNM4      VPCY2 = SY*(1.0 + 2.0*CY)/3.0      VPCSY = ( - DSVN + 2.0*SY**2)/3.0      VPSY2 = 2.0*SY*DSVN/3.0      VPCDX = RH*(2.0*CX*SX/FNM4 + SX/WM2N     1 - (RH*(NB/WM2N + 0.5*NB/FNM4) + 0.5)*SY/WMN)      VPCDM = RH*CX*SY/WM5N - RH*(1.0/WM2N - 1.0/WM5N)*SY     1 + WMN*H*H0*SX*DSVN/WM2N     2 + 0.5*RH*(1.0/WM2N - 3.0*WMN/(WM2N*WM5N))*SX*CY      VPSDX = RH*( - (CX - CY)/(WMN*WM2N)     1 - (1.0 - CY)/(WMN*FNM4) + 2.0*H0**2*SX**2/FNM4)      VPSDM = RH*(0.5*(1.0 - 3.0*WMN/WM5N)*CY*DISN/WM2N     1 - CX*DSVN/WM2N + SX*SY/WM5N)      VPDX2 = RH**2*(- 2.0*CX*SX/(WMN*FNM4) - 2.0*SX/(WMN*WM2N)     1 + (RH*NB*(2.0/WM2N + 0.5/FNM4) + 1.5)*SY/WMN**2)      VPDDM = RH*( - RH*CX*SY/(WMN*WM5N)     1 + 0.5*RH*( - 1.0/WMN + 3.0/WM5N)*SX*CY/WM2N     2 - H*H0*SX*DSVN/WM2N     3 + 0.5*SMLCV/WMN     4 + RH*SY*(1.0/WM2N - 1.0/WM5N)/WMN)C      R(1,3) = R(1,3) + VR*H0**2*(- NMTB*HSCDY + NB*HSSY2)      R(1,4) = R(1,4) - VR*HSCSY - NMTB*VR*HSSDY      R(2,3) = R(2,3) + VR*H0**2*(- NMTB*HPCDY + NB*HPSY2)      R(2,4) = R(2,4) - VR*H0**2*HPCSY     1 - NMTB*VR*HPSDY      R(3,1) = R(3,1) - 2.0*VR*NMB*VSCDM     1 - VR*WMN*H0**2*VSSSM      R(3,2) = R(3,2) + VR*(VSCSM - 2.0*NMB*VSSDM)      R(3,6) = R(3,6) + VR*H0*(NB*VSDY + VSSSM - 2.0*NMB*VSDDM)     1 - VR*H0*DSVN      R(4,1) = R(4,1) - VR*H0**2*(2.0*NMB*VPCDM + WMN*VPSSM)     1 - VR*H0**2*CX*SY      R(4,2) = R(4,2) + VR*H0**2*(VPCSM - 2.0*NMB*VPSDM)     1 - VR*H0**2*SX*SY      R(4,6) = R(4,6)     1 + VR*H0*(NB*VPDY + VPSSM - 2.0*NMB*VPDDM)     2 - VR*H0*(SY + H0**2*DISN)C      GLUG1 = H0**3*TBTNP*HSCCM      GLUG2 = H0**3*NPMV*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*     1 (HSCY - HSCCM)      GLUG3 = H0**3*NPMV*(BEB*WMN/WM5N + NMB)*HSSSM      GLUG4 = H0**3*(- 2.*TNMB*NPMV + NMTB*TVMNP)*HSCCM/WM2N      GLUG5 = 2.0*H0**3*TNMB*NPMV*HSCX2/WM2N      GLUG6 = - H0**3*NMTB*TVMNP*HSCY2/WM2N      GLUG7 = NB*WMN*H0**3*(TVMNP - NPMV)*HSSSM/WM2N      GLUG8 = WMN**2*H0**3*NPMV*HSSX2/WM2N      GLUG9 = - NB**2*H0**3*TVMNP*HSSY2/WM2N      T(1,4) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9      GLUG1 = H0*TBTNP*HSCSM      GLUG2 = 0.5*H0*NPMV*(HSSY - HSCSM)      GLUG3 = H0*NPMV*( - 2.0*NMB + 0.5*WMN)*(HSSY + HSCSM)/WM5N      GLUG4 = H0*NPMV*(4.0*NMB - WMN)*HSSCM/WM5N      GLUG5 = H0*NPMV*(2.0*TNMB - WMN)*H0**2*HSCSX/WM2N      GLUG6 = - H0*(2.*TNMB*NPMV - NMTB*TVMNP)*HSCSM/WM2N      GLUG7 = - H0*WMN*(TVMNP - NPMV)*HSSCM/WM2N      GLUG8 = 2.0*BEB*H0*TVMNP*HSCSY/WM2N      GLUG9 = H0*NPMV*(SX - SY)/WM2N      T(1,7) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9      GLUG1 = H0*TBTNP*HSSCM      GLUG2 = - NPR*H0*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*HSSCM      GLUG3 = - BEB*H0*NPMV*(HSSY + HSCSM)/WM5N      GLUG4 = NMB*H0*NPMV*(HSSY - HSCSM)/WMN      GLUG5 = NPMV*(2.0*TNMB - WMN)*H0**3*HSCSX/WM2N      GLUG6 = - H0*NB*(TVMNP - NPMV)*HSCSM/WM2N      GLUG7 = - H0*(2.0*TNMB*NPMV - NMTB*TVMNP)*HSSCM/WM2N      GLUG8 = 2.0*BEB*H0*TVMNP*HSCSY/WM2N      T(1,5) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8      GLUG1 = H0*TBTNP*HSSSM      GLUG2 = - H0*NPMV*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*     1 HSSSM      GLUG3 = H0*NPMV*(4.0*NMB/WMN - 1.0)*(HSCY - HSCCM)/WM5N      GLUG4 = H0*(TVMNP - NPMV)*HSCCM/WM2N      GLUG5 = H0*NPMV*HSCX2/WM2N      GLUG6 = - H0*(2.0*TNMB*NPMV - NMTB*TVMNP)*HSSSM/WM2N      GLUG7 = 2.0*H0*TNMB*NPMV*HSSX2/WM2N      GLUG8 = - H0*TVMNP*HSCY2/WM2N      GLUG9 = - H0*NMTB*TVMNP*HSSY2/WM2N      T(1,8) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9      GLUG1 = NPMV*H0**2*HSCY      GLUG2 = TBTNP*HSDCM      GLUG3 = NMTB*VR*H0**2*HSCDY      GLUG4 = - NB*VR*H0**2*HSSY2      GLUG5 = 2.0*NPMV*H0**2*BEB*(HSCY - HSCCM)/(WMN*WM5N)      GLUG6 = - NPMV*(NMB/WMN + BEB/WM5N)*H0**2*HSSSM      GLUG7 = - NPMV*(0.5*NB - NMB/WMN)*H0**2*HSLSY      GLUG8 = TMN*NPMV*H0**2*(HSCX - HSCY)/WM2N      GLUG9 = 2.0*TNMB*NPMV*H0**2*HSCDX/WM2N      GLUGA = 3.0*VR*NB*H0**2*HSSSM/WM2N      GLUGB = - WMN*NPMV*H0**2*HSSX2/WM2N      GLUGC = - (2.*TNMB*NPMV - NMTB*TVMNP)*HSDCM/WM2N      GLUGD = - NMTB*TVMNP*H0**2*HSCDY/WM2N      GLUGE = - NB*TVMNP*H0**2*HSSY2/WM2N      T(1,18) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9 + GLUGA + GLUGB + GLUGC     2 + GLUGD + GLUGE      GLUG1 = TBTNP*HSDSM      GLUG2 = VR*HSCSY      GLUG3 = NMTB*VR*HSSDY      GLUG4 = NPMV*(2.0*NMB/WMN - 0.5)*(HSSY + HSCSM)/WM5N      GLUG5 = - 0.5*NPMV*(HSSY - HSCSM)/WMN      GLUG6 = 0.5*NPMV*HSSY      GLUG7 = 0.5*NPMV*HSLCY      GLUG8 = NPMV*NMB*HSGLP/WMN      GLUG9 = NPMV*(- 4.0*NMB/WMN + 1.0)*HSSCM/WM5N      GLUGA = NPMV*H0**2*HSCSX/WM2N      GLUGB = TMN*NPMV*HSSX/WM2N      GLUGC = 2.0*TNMB*NPMV*HSSDX/WM2N      GLUGD = - VR*HSSCM/WM2N      GLUGE = TVMNP*HSCSY/WM2N      GLUGF = - TMN*NPMV*HSSY/WM2N      GLUGG = - (2.*TNMB*NPMV - NMTB*TVMNP)*HSDSM/WM2N      GLUGH = - NMTB*TVMNP*HSSDY/WM2N      T(1,19) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9 + GLUGA + GLUGB + GLUGC     1 + GLUGD + GLUGE + GLUGF + GLUGG + GLUGH      GLUG1 = H0**3*TBTNP*HPCCM      GLUG2 = H0**3*NPMV*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*     1 (HPCY - HPCCM)      GLUG3 = H0**3*NPMV*(BEB*WMN/WM5N + NMB)*HPSSM      GLUG4 = H0**3*(- 2.*TNMB*NPMV + NMTB*TVMNP)*HPCCM/WM2N      GLUG5 = 2.0*H0**3*TNMB*NPMV*HPCX2/WM2N      GLUG6 = - H0**3*NMTB*TVMNP*HPCY2/WM2N      GLUG7 = NB*WMN*H0**3*(TVMNP - NPMV)*HPSSM/WM2N      GLUG8 = WMN**2*H0**5*NPMV*HPSX2/WM2N      GLUG9 = - NB**2*H0**3*TVMNP*HPSY2/WM2N      GLUGA = H0**3*NPMV*(2.0*WMN*CX*SX     1 - NB*CX*SY - WMN*CY*SX)/WM2N      T(2,4) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9 + GLUGA      GLUG1 = H0**3*TBTNP*HPCSM      GLUG2 = 0.5*H0**3*NPMV*(HPSY - HPCSM)      GLUG3 = H0**3*NPMV*( - 2.0*NMB + 0.5*WMN)*(HPSY + HPCSM)/WM5N      GLUG4 = H0**3*NPMV*(4.0*NMB - WMN)*HPSCM/WM5N      GLUG5 = H0**3*NPMV*(2.0*TNMB - WMN)*HPCSX/WM2N      GLUG6 = - H0**3*(2.*TNMB*NPMV - NMTB*TVMNP)*HPCSM/WM2N      GLUG7 = - H0**3*WMN*(TVMNP - NPMV)*HPSCM/WM2N      GLUG8 = 2.0*BEB*H0**3*TVMNP*HPCSY/WM2N      GLUG9 = H0**3*NPMV*( - WMN*DISN*(1.0 + CY)     1 + WMN*(2.0*SX**2 - SX*SY))/WM2N      T(2,7) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9      GLUG1 = H0**3*TBTNP*HPSCM      GLUG2 = - NPMV*H0**3*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*HPSCM      GLUG3 = - BEB*H0**3*NPMV*(HPSY + HPCSM)/WM5N      GLUG4 = NMB*H0**3*NPMV*(HPSY - HPCSM)/WMN      GLUG5 = H0**3*NPMV*(2.0*TNMB - WMN)*HPCSX/WM2N      GLUG6 = - H0**3*NB*(TVMNP - NPMV)*HPCSM/WM2N      GLUG7 = - H0**3*(2.0*TNMB*NPMV - NMTB*TVMNP)*HPSCM/WM2N      GLUG8 = 2.0*BEB*H0**3*TVMNP*HPCSY/WM2N      GLUG9 = - H0**3*NPMV*(WMN*DISN + NB*CX*DSVN     1 + NB*SX*SY - 2.0*WMN*SX**2)/WM2N      T(2,5) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9      GLUG1 = H0*TBTNP*HPSSM      GLUG2 = - H0*NPMV*(0.5*(1.0 - WMN/WM5N) + 2.0*NMB/WM5N)*     1 HPSSM      GLUG3 = H0*NPMV*(4.0*NMB/WMN - 1.0)*(HPCY - HPCCM)/WM5N      GLUG4 = H0*(TVMNP - NPMV)*HPCCM/WM2N      GLUG5 = H0*NPMV*HPCX2/WM2N      GLUG6 = - H0*(2.0*TNMB*NPMV - NMTB*TVMNP)*HPSSM/WM2N      GLUG7 = 2.0*H0**3*TNMB*NPMV*HPSX2/WM2N      GLUG8 = - H0*TVMNP*HPCY2/WM2N      GLUG9 = - H0*NMTB*TVMNP*HPSY2/WM2N      GLUGA = H0*NPMV*(CX*SY + CY*SX - 2.0*CX*SX)/WM2N      T(2,8) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9 + GLUGA      GLUG1 = H0**2*TBTNP*HPDCM      GLUG2 = NPMV*H0**2*HPCY      GLUG3 = NMTB*VR*H0**2*HPCDY      GLUG4 = - NB*VR*H0**2*HPSY2      GLUG5 = 2.0*NPMV*H0**2*BEB*(HPCY - HPCCM)/(WMN*WM5N)      GLUG6 = - NPMV*(NMB/WMN + BEB/WM5N)*H0**2*HPSSM      GLUG7 = - NPMV*(0.5*NB - NMB/WMN)*H0**2*HPLSY      GLUG8 = TMN*NPMV*H0**2*(HPCX - HPCY)/WM2N      GLUG9 = 2.0*TNMB*NPMV*H0**2*HPCDX/WM2N      GLUGA = 3.0*VR*NB*H0**2*HPSSM/WM2N      GLUGB = - WMN*NPMV*H0**4*HPSX2/WM2N      GLUGC = - (2.*TNMB*NPMV - NMTB*TVMNP)*H0**2*HPDCM/WM2N      GLUGD = - NMTB*TVMNP*H0**2*HPCDY/WM2N      GLUGE = - NB*TVMNP*H0**2*HPSY2/WM2N      GLUGF = H0**2*NPMV*(SX*(CY - CX)     1 + H0*DISP*(WMN*SX - NB*SY))/WM2N      T(2,18) = GLUG1 + GLUG2 + GLUG3 + GLUG4 + GLUG5     1 + GLUG6 + GLUG7 + GLUG8 + GLUG9 + GLUGA + GLUGB + GLUGC     2 + GLUGD + GLUGE + GLUGF      GLUG1 = H0**2*TBTNP*HPDSM      GLUG2 = VR*H0**2*HPCSY      GLUG3 = NMTB*VR*HPSDY      GLUG4 = NPMV*(2.0*NMB/WMN - 0.5)*H0**2*(HPSY + HPCSM)/WM5N      GLUG5 = - 0.5*NPMV*H0**2*(HPSY - HPCSM)/WMN      GLUG6 = 0.5*NPMV*H0**2*HPSY      GLUG7 = 0.5*NPMV*H0**2*HPLCY      GLUG8 = NPMV*NMB*H0**2*HPGLP/WMN      